def image(self, image_id: str, actor: str) -> tuple:
    with self.connect() as db:
        row = db.execute("SELECT body,format,state FROM images WHERE id=?", (image_id,)).fetchone()
    if row is None: raise DomainError(404, "Image not found")
    if row["state"] != "published":
        try: self.authorize(actor, "reviewer")
        except DomainError as exc: raise DomainError(404, "Image not found") from exc
    self.bo.record("image", "return", {"image_id": image_id, "actor": actor or ""}, {"format": row["format"], "byte_count": len(row["body"])}, image_id)
    return row["body"], "image/png" if row["format"] == "PNG" else "image/jpeg"

