def transition(self, state: str, event: str, context: dict, payload: dict) -> dict:
    machine = self.definition
    if state not in machine["states"] or event not in machine["events"]:
        raise ValueError("Unknown state or event")
    if set(context) != set(machine["context"]) or set(payload) != set(machine["events"][event]["payload"]):
        raise ValueError("Context or payload fields differ from declaration")
    for name, spec in machine["context"].items():
        if value_errors(context[name], spec, name): raise ValueError("Invalid context value")
    for name, spec in machine["events"][event]["payload"].items():
        if value_errors(payload[name], spec, name): raise ValueError("Invalid event payload")
    evaluated = {}
    for item in machine["transitions"]:
        if item["source"] != state or item["trigger"] != event: continue
        allowed = True
        for guard in item.get("conditions", []):
            evaluated[guard] = self.guards[guard](context, payload)
            if not evaluated[guard]:
                allowed = False
                break
        if allowed:
            return {"before": state, "state": item["dest"], "event": event, "guards": evaluated}
    raise ValueError("No enabled transition")

