def login(self, username: str, password: str) -> dict:
    with self.connect() as db:
        row = db.execute("SELECT * FROM accounts WHERE username=?", (username,)).fetchone()
    allowed = bool(row and check_password_hash(row["password_hash"], password))
    result = {"authenticated": allowed, "role": row["role"] if allowed else ""}
    self.bo.record("login", "return", {"username": username[:100], "password_present": bool(password)}, result)
    if not allowed: raise DomainError(401, "Invalid credentials")
    return {"username": username, "role": row["role"]}

