def review(self, actor: str, image_id: str, decision: str) -> dict:
    role = self.authorize(actor, "reviewer")
    if decision not in {"approve", "reject"}: raise DomainError(400, "Unknown review decision")
    with self.connect() as db:
        db.execute("BEGIN IMMEDIATE")
        row = db.execute("SELECT * FROM images WHERE id=?", (image_id,)).fetchone()
        if row is None: raise DomainError(404, "Image not found")
        try:
            change = self.machine.transition(row["state"], decision, {"format": row["format"], "uploader": row["uploader"]}, {"role": role})
        except ValueError as exc:
            raise DomainError(409, "Image is no longer pending") from exc
        revision = row["revision"] + 1
        db.execute("UPDATE images SET state=?,revision=?,build_id=? WHERE id=?", (change["state"], revision, self.build_id, image_id))
        db.execute("INSERT INTO journal(image_id,event,previous,state,revision) VALUES(?,?,?,?,?)", (image_id, decision, row["state"], change["state"], revision))
    self.bo.record("review", "commit", {"actor": actor, "image_id": image_id, "decision": decision}, {"before": row["state"], "state": change["state"], "revision": revision, "reviewer_guard": change["guards"]["reviewer"]}, image_id)
    return {"id": image_id, "state": change["state"]}
